{{- if eq (include "agenta.agentRunner.enabled" .) "true" }}
apiVersion: apps/v1
kind: Deployment
metadata:
  name: {{ include "agenta.agentRunner.serviceName" . }}
  labels:
    {{- include "agenta.labels" . | nindent 4 }}
    app.kubernetes.io/component: runner
spec:
  replicas: {{ include "agenta.agentRunner.replicas" . }}
  {{- if $runner.strategy }}
  strategy:
    {{- toYaml $runner.strategy | nindent 4 }}
  {{- else if eq (include "agenta.agentRunner.localProviderEnabled" .) "true" }}
  {{- /* A local sandbox is a process inside the pod that started it, so the
         local provider runs one runner pod at a time: the old pod stops
         before the new one starts. */}}
  strategy:
    type: Recreate
  {{- else }}
  {{- /* Each turn is bound to its pod and Stop goes to that pod, so a new pod
         can take new turns while an old one finishes its own: start the new
         pod, wait until it is ready, then drain the old one. */}}
  strategy:
    type: RollingUpdate
    rollingUpdate:
      maxSurge: 1
      maxUnavailable: 0
  {{- end }}
  selector:
    matchLabels:
      {{- include "agenta.selectorLabels" . | nindent 6 }}
      app.kubernetes.io/component: runner
  template:
    metadata:
      labels:
        {{- include "agenta.selectorLabels" . | nindent 8 }}
        app.kubernetes.io/component: runner
    spec:
      {{- include "agenta.imagePullSecrets" . | nindent 6 }}
      serviceAccountName: {{ include "agenta.serviceAccountName" . }}
      {{- /* Default 300 s: in-flight agent turns need room to finish. */}}
      terminationGracePeriodSeconds: {{ include "agenta.agentRunner.terminationGracePeriodSeconds" . }}
      {{- with $runner.podSecurityContext }}
      securityContext:
        {{- toYaml . | nindent 8 }}
      {{- end }}
      containers:
        - name: runner
          image: {{ include "agenta.agentRunnerImage" . }}
          imagePullPolicy: {{ include "agenta.agentRunner.pullPolicy" . }}
          {{- /* FUSE for the durable session cwd: geesefs mounts the store prefix on-host for
                 local sandboxes, which needs SYS_ADMIN + /dev/fuse. Only granted when the store
                 is on AND agentRunner.fuse.enabled is true; an explicit runner.securityContext
                 (if set) overrides this default. Set agentRunner.fuse.enabled=false on a cluster
                 that rejects SYS_ADMIN or a hostPath, such as GKE Autopilot. */ -}}
          {{- if $runner.securityContext }}
          securityContext:
            {{- toYaml $runner.securityContext | nindent 12 }}
          {{- else if and (eq (include "agenta.store.enabled" .) "true") (eq (include "agenta.agentRunner.fuse.enabled" .) "true") }}
          securityContext:
            capabilities:
              add: ["SYS_ADMIN"]
          {{- end }}
          ports:
            - name: http
              containerPort: {{ include "agenta.agentRunner.port" . }}
              protocol: TCP
          env:
            {{- /* Narrow by design (runner-selfhosting-cleanup): a local harness process shares
                   this container, so anything here is readable from /proc. Only the runner's own
                   config and the API URL it needs to reach the platform — never the full
                   commonEnv (DB/auth/crypt/license/redis/store secrets). See
                   tests/test_runner_secret_absence.py. */}}
            - name: AGENTA_API_URL
              port: http
            periodSeconds: 10
            timeoutSeconds: 5
            failureThreshold: 3
          {{- with $runner.lifecycle }}
          lifecycle:
            {{- toYaml . | nindent 12 }}
          {{- else }}
          {{- /* Default: hold the container open for 10 s after Kubernetes
                 sends the stop signal, so the load balancer finishes taking
                 this pod out of rotation before the process goes away. */}}
          lifecycle:
            preStop:
              exec:
                command: ["sleep", "10"]
          {{- end }}
          {{- with $runner.resources }}
          resources:
            {{- toYaml . | nindent 12 }}
          {{- end }}
          {{- if and (eq (include "agenta.store.enabled" .) "true") (eq (include "agenta.agentRunner.fuse.enabled" .) "true") }}
          volumeMounts:
            - name: fuse
              mountPath: /dev/fuse
          {{- end }}
      {{- if and (eq (include "agenta.store.enabled" .) "true") (eq (include "agenta.agentRunner.fuse.enabled" .) "true") }}
      volumes:
        - name: fuse
          hostPath:
            path: /dev/fuse
            type: CharDevice
      {{- end }}
      {{- with $runner.priorityClassName }}
      priorityClassName: {{ . | quote }}
      {{- end }}
      {{- with $runner.nodeSelector }}
